#!/bin/bash
# Run smcs on the Mono bundled with Unity 3.5.7 for macOS to build an Assembly-CSharp.dll byte-identical to the original (run inside the build Linux).
# Usage: smcs_mac.sh <repo> <sources.rsp> <out.dll>
#   sources.rsp is generated by toolchain/build_dll.py (source paths relative to repo, already in compile order).
#
# Why not the Windows smcs: smcs.exe and the assemblies are byte-identical to the Mac version; the differences lie entirely in the runtime —
#   1. Windows mono.exe defaults to the 2.0.0.0 mscorlib, while the original references the 2.0.5.0 one from the unity profile;
#   2. Mono's Reflection.Emit qsorts the CustomAttribute table by Parent only (unstable), so the final order of multiple attributes on the same target
#      depends on the C library's qsort. The original was built on Mac; the MSVC qsort on Windows orders them differently.
# Here Mac mono (loaded by maloader32) + the qsort in darwin_shim transcribed from Apple Libc match the original on both counts.
# The resulting DLL is byte-identical to the original except for the MVID and PE timestamp (which change on every build).
set -euo pipefail

# ---- Constants ----
LOADER32=/work/ckz2/maloader32/ld-mac
SHIM=/work/ckz2/darwin_shim32.so
UNITY_MONO_DIR=/work/ckz2/unity357_mono
# iOS build of UnityEngine.dll from the Unity installer (byte-identical to the game's)
UNITY_ENGINE=/work/ckz2/unity357/PlaybackEngines/iPhonePlayer/Managed/UnityEngine.dll
UNITY_PROFILE=$UNITY_MONO_DIR/lib/mono/unity
# Arguments of Unity 3.5.7 UnityEditor.Scripting.Compilers.CSharpCompiler
SMCS_FLAGS="-debug -target:library -nowarn:0169"

if [ $# -ne 3 ]; then
    echo "usage: smcs_mac.sh <repo> <sources.rsp> <out.dll>" >&2
    exit 2
fi
repo=$(realpath "$1")
response_file=$(realpath "$2")
output=$(realpath -m "$3")
mkdir -p "$(dirname "$output")"

# Reference order as in the original build; the third-party LitJSON.dll comes from the repo's Assets/3rd_party/,
# the Unity ones from the installer (byte-identical to the game's bundled ones)
reference_args="-r:$UNITY_ENGINE -r:$repo/Assets/3rd_party/LitJSON.dll -r:$UNITY_PROFILE/System.Core.dll -r:$UNITY_PROFILE/System.Xml.dll"

# Source paths in the response file are relative to repo, so run inside repo
cd "$repo"
export MONO_PATH=$UNITY_PROFILE
export MONO_CFG_DIR=$UNITY_MONO_DIR/etc
export GC_DONT_GC="yes please"
log=$(mktemp)
# shellcheck disable=SC2086
LD_PRELOAD=$SHIM "$LOADER32" "$UNITY_MONO_DIR/bin/mono" "$UNITY_PROFILE/smcs.exe" \
    $SMCS_FLAGS "-out:$output" $reference_args "@$response_file" > "$log" 2>&1 || {
    # maloader prints an "undefined symbol" line for every unimplemented Darwin symbol; on failure, show only the other lines
    grep -v "undefined symbol" "$log" | grep -v "warning CS" | tail -20 >&2
    rm -f "$log"
    exit 1
}
warnings=$(grep -c "warning CS" "$log" || true)
rm -f "$log"
echo "smcs (Mac mono): $warnings warnings -> $output"
